import { NextResponse, type NextRequest } from "next/server";
import { readSessionToken } from "@/lib/session";

const API_BASE =
  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8001/api/v1";

/**
 * POST /api/billing/invoices — server-side proxy for the billing write path.
 * The JWT lives in an httpOnly cookie; the client never sees it. The
 * Idempotency-Key generated by the browser for one checkout attempt is passed
 * through verbatim so a retry after a network blip replays instead of
 * double-billing.
 */
export async function POST(request: NextRequest) {
  const token = await readSessionToken();
  if (!token) {
    return NextResponse.json(
      {
        error: "Sign in to create bills",
        code: "unauthenticated",
        details: {},
      },
      { status: 401 },
    );
  }

  const idempotencyKey = request.headers.get("Idempotency-Key");
  const upstreamBody = await request.text();

  const res = await fetch(`${API_BASE}/invoices`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
      ...(idempotencyKey ? { "Idempotency-Key": idempotencyKey } : {}),
    },
    body: upstreamBody,
    cache: "no-store",
  });

  // Forward the API's response verbatim — including the standard error
  // envelope {error, code, details} — so the cart can localize the message.
  return new NextResponse(await res.arrayBuffer(), {
    status: res.status,
    headers: {
      "Content-Type": res.headers.get("content-type") ?? "application/json",
    },
  });
}
